using System.Security.Claims;using System.Security.Cryptography;using System.Text;using Asp.Versioning;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using SmartFarm.Repositories.Entities;using SmartFarm.Services;using SmartFarm.Services.Models;using SmartFarm.Services.Services;
namespace SmartFarm.Api.Controllers;
[ApiController,ApiVersion(1.0),Route("api/v{version:apiVersion}/iot")]
public class DeviceTelemetryController(TelemetryService service,MqttOptions options):ControllerBase
{private void AuthorizeDevice(){var supplied=Request.Headers["X-Device-Key"].ToString();if(string.IsNullOrWhiteSpace(options.IngestApiKey)||!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(supplied),Encoding.UTF8.GetBytes(options.IngestApiKey)))throw new AppException(401,"Invalid device API key.");}[HttpPost("telemetry")][AllowAnonymous]public async Task<IActionResult>Ingest(TelemetryIngestRequest request){AuthorizeDevice();return Ok(ApiResponse<object>.Ok(await service.IngestAsync(request)));}[HttpPost("heartbeat")][AllowAnonymous]public async Task<IActionResult>Heartbeat(HeartbeatRequest request){AuthorizeDevice();await service.HeartbeatAsync(request.DeviceCode,request.RecordedAt);return Ok(ApiResponse<object>.Ok(new{},"Heartbeat accepted"));}}
[ApiController,ApiVersion(1.0),Route("api/v{version:apiVersion}/staff/telemetry"),Authorize(Roles=RoleNames.Staff+","+RoleNames.Admin)]
public class StaffTelemetryController(TelemetryService service):ControllerBase
{[HttpGet("trays/{trayId:int}/latest")]public async Task<IActionResult>Latest(int trayId)=>Ok(ApiResponse<object>.Ok(await service.LatestStaffAsync(trayId)));[HttpGet("trays/{trayId:int}/history")]public async Task<IActionResult>History(int trayId,[FromQuery]QueryRequest query,[FromQuery]DateTime? from,[FromQuery]DateTime? to)=>Ok(ApiResponse<object>.Ok(await service.HistoryStaffAsync(trayId,query,from,to)));}
[ApiController,ApiVersion(1.0),Route("api/v{version:apiVersion}/rentals/{rentalId:int}/telemetry"),Authorize(Roles=RoleNames.Customer)]
public class CustomerTelemetryController(TelemetryService service):ControllerBase
{private int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet("latest")]public async Task<IActionResult>Latest(int rentalId)=>Ok(ApiResponse<object>.Ok(await service.LatestCustomerAsync(UserId,rentalId)));[HttpGet("history")]public async Task<IActionResult>History(int rentalId,[FromQuery]QueryRequest query,[FromQuery]DateTime? from,[FromQuery]DateTime? to)=>Ok(ApiResponse<object>.Ok(await service.HistoryCustomerAsync(UserId,rentalId,query,from,to)));}
